UPDATE businesses SET description = 'Astram Technologies (PTY) Ltd, based in Amberfield Glen, Centurion, develops ASTRAM, a cloud-based quality management and inspection reporting platform aimed at inspection companies, asset managers and industrial operators in South Africa, India and Germany. The platform links inspection, asset and financial operations through sixteen connected modules so that a field finding can flow through to a report, repair job and invoice. Its Dashboard module gives real-time KPIs across inspection status, asset health, open jobs and financial summaries, while Asset Management tracks equipment from registration to end-of-life with maintenance history, depreciation and parts-used traceability. Inspection Management allows scheduling, assigning, conducting and reporting of inspections on mobile or desktop with image-backed findings, and a dedicated Non-Destructive Testing module supports UT, RT, MT and PT workflows with acceptance-criteria validation and QR-verified certificates. Job Management tracks delegated jobs to documented completion, Maintenance issues preventive schedules and alerts, a Financial Portal covers sales, purchases, banking and a full accountant suite, a Client Portal gives clients read-only access to their assets and reports, and an Offline Sync feature allows field data capture without connectivity.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'http://astramtech.com/'), description_enriched_at = datetime('now') WHERE slug = 'astram-technologies-pty-ltd-amberfield-glen' AND description = 'Astram Technologies is an industrial software provider in Amberfield Glen, Centurion, offering inspection automation, preventive maintenance and quality management system tools for clients in manufacturing, energy, telecommunications and pharmaceuticals.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
